mapper.select:
SELECT v.id, v.document_id, v.version_no, v.file_object_id, v.original_name, v.content_type, v.byte_size, v.sha256, v.status, v.is_current, v.created_at, v.created_by, v.change_reason, d.employee_id FROM archive_version v JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id WHERE v.id = #{versionId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{employeeId} AND 1 = 0
LIMIT 1

SELECT v.id AS version_id, f.object_key, v.original_name, v.content_type, v.byte_size, v.sha256, d.document_type, e.id AS employee_id, e.department_id FROM archive_version v JOIN archive_document d ON d.id = v.document_id JOIN file_object f ON f.id = v.file_object_id JOIN employee e ON e.id = d.employee_id WHERE v.id = #{versionId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{employeeId} AND 1 = 0
LIMIT 1
